def get_progress(transport, lesson_id):
    data = transport(lesson_id, timeout=2)
    if not isinstance(data, dict) or data.get('lesson_id') != lesson_id:
        raise ValueError('Unexpected progress record')
    if type(data.get('done')) is not bool:
        raise ValueError('done must be true or false')
    return data['done']

def local_stand_in(lesson_id, *, timeout):
    assert timeout > 0
    return {'lesson_id': lesson_id, 'done': True}

assert get_progress(local_stand_in, 'loops') is True
try:
    get_progress(lambda lesson_id, timeout: {'lesson_id': 'other', 'done': True}, 'loops')
except ValueError:
    pass
else:
    raise AssertionError('mismatched ID must be rejected')
